B.br3=new A.hk("1. OBJETIVO",null)
B.bqi=new A.kr("Esta Politica de Privacidade explica como a DeliGo recolhe, utiliza, partilha e protege dados pessoais de clientes, estafetas, restaurantes e administradores no ambito da utilizacao da aplicacao e servicos associados.",null)
B.brb=new A.hk("2. RESPONSAVEL PELOS DADOS",null)
B.bqs=new A.kr("A Deligo Triunfal, LDA atua como responsavel pelo tratamento dos dados pessoais recolhidos atraves da plataforma DeliGo.",null)
B.brd=new A.hk("3. DADOS QUE PODEMOS RECOLHER",null)
B.brN=new A.xC("3.1 Dados de conta",null)
B.aEz=s(["Nome e dados de perfil","Numero de telefone","Email, quando fornecido","Foto de perfil, quando enviada"],t.s)
B.boH=new A.ko(B.aEz,null)
B.brX=new A.xC("3.2 Dados de verificacao e compliance",null)
B.aIL=s(["Documentos de identificacao e respetiva informacao","Selfie ou foto para verificacao","Dados necessarios para prevencao de fraude e cumprimento legal"],t.s)
B.boj=new A.ko(B.aIL,null)
B.brP=new A.xC("3.3 Dados de pedidos e pagamentos",null)
B.aAt=s(["Historico de pedidos","Endereco de entrega e coordenadas relacionadas","Valores, taxas e estado das transacoes","Registos de wallet, depositos e levantamentos"],t.s)
B.bon=new A.ko(B.aAt,null)
B.brQ=new A.xC("3.4 Dados de localizacao",null)
B.ayi=s(["Localizacao aproximada e precisa para mapas e cobertura","Rastreamento do pedido e do estafeta","Calculo de rotas e tempos estimados"],t.s)
B.bof=new A.ko(B.ayi,null)
B.brL=new A.xC("3.5 Comunicacoes e dados tecnicos",null)
B.aBM=s(["Mensagens de chat e suporte","Notificacoes push e preferencias","Identificadores da aplicacao, analytics, crash logs e diagnosticos"],t.s)
B.boh=new A.ko(B.aBM,null)
B.brA=new A.hk("4. COMO UTILIZAMOS OS DADOS",null)
B.aI5=s(["Criar e gerir contas","Processar pedidos, entregas e levantamentos","Processar pagamentos e reconciliacoes","Ativar chat, notificacoes e suporte","Prevenir fraude e reforcar a seguranca","Cumprir obrigacoes legais, fiscais e regulatorias","Melhorar o desempenho e a confiabilidade da plataforma"],t.s)
B.bor=new A.ko(B.aI5,null)
B.br6=new A.hk("5. PARTILHA DE DADOS",null)
B.bqm=new A.kr("Clientes, restaurantes e estafetas podem ver os dados minimos necessarios para executar um pedido. Tambem podemos partilhar dados com prestadores de pagamentos, infraestrutura, analytics, suporte tecnico e autoridades competentes quando exigido por lei.",null)
B.br4=new A.hk("6. RETENCAO",null)
B.bqz=new A.kr("Mantemos os dados pelo tempo necessario para prestar o servico, cumprir requisitos legais, prevenir fraude, resolver disputas e manter a integridade operacional e financeira da plataforma.",null)
B.bry=new A.hk("7. SEGURANCA",null)
B.bqe=new A.kr("Adotamos medidas tecnicas e organizacionais para proteger os dados, incluindo controlos de acesso, autenticacao, validacoes do lado do servidor e monitorizacao. Nenhum sistema e 100% seguro, mas trabalhamos continuamente para reduzir riscos.",null)
B.bru=new A.hk("8. DIREITOS DO UTILIZADOR",null)
B.az6=s(["Solicitar acesso aos seus dados","Solicitar correcao de dados","Solicitar eliminacao ou encerramento de conta, quando possivel","Retirar consentimentos, quando o tratamento depender de consentimento"],t.s)
B.boJ=new A.ko(B.az6,null)
B.bqx=new A.kr("Os pedidos de eliminacao de conta podem ser feitos diretamente na aplicacao DeliGo, na secao Configuracoes. Pedidos com saldo, pedidos ativos, disputas ou obrigacoes legais podem passar por revisao manual antes da eliminacao definitiva.",null)
B.brn=new A.hk("9. TECNOLOGIAS SEMELHANTES A COOKIES",null)
B.bqd=new A.kr("A aplicacao pode utilizar identificadores e tecnologias semelhantes para manter sessao, prevenir fraude, suportar analytics e melhorar o servico.",null)
B.brz=new A.hk("10. ALTERACOES",null)
B.bqg=new A.kr("Podemos atualizar esta politica periodicamente. A versao mais recente deve estar disponivel nos canais oficiais da DeliGo.",null)
B.a2H=new A.hk("11. CONTACTO",null)
